) AS (
  VALUES 
    (490::BIGINT, 'Es un gran profe, lo motiva mucho a uno a agarrarle gusto a las mates y a el estudio, es comico y disfrutar compartir con los estudiantes, es bastante carga en mate, uno debe comprender que si bien parte de la materia la vemos en la U también a nosotros como estudiantes nos toca estudiar en casa.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2026-04-25T00:00:00+00:00'::TIMESTAMPTZ, 'c15ac3a58d614d222c511cf54ff752df9da5bc9bc909f3f4392d50990895a487'::TEXT, ARRAY[1018, 563]::BIGINT[]),
    (490::BIGINT, 'El profesor no prepara la clase con antelación. Literal toma un pilot, da las demostraciones de los criterios y asume los temas como vistos. Está en el congreso entonces puede que ni dé la clase y mande a estudiar con la cátedra. Por favor quiérase un poco y no matricule con él.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2025-09-18T00:00:00+00:00'::TIMESTAMPTZ, 'c4aff41e40befcd0122e63a61dc479cea48cd15ab056c9e07a63696d8c4a8755'::TEXT, ARRAY[634]::BIGINT[]),
    (490::BIGINT, 'Tiene un gran manejo de los temas. Se interesa en que uno realmente aprenda entonces si usted muestra interes el hace lo posible para explicarle y que le vaya bien, eso si no regala puntos. Me ayudo a no temerle tanto a los cursos de mate. Eso si hay que estudiar los temas por semana.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2025-07-02T00:00:00+00:00'::TIMESTAMPTZ, '2cf411f2342f65c1494d61e25a0dadbeaa158483dcc9fc725995e731192700cc'::TEXT, ARRAY[634]::BIGINT[]),
    (490::BIGINT, 'Pone rubros de calificación muy complicados, es bueno explicando, pero no brinda mucho apoyo'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2025-03-28T00:00:00+00:00'::TIMESTAMPTZ, '51b7462853c6c166acb4ba2dbe700ddac9b286a178054e21e444723a7e35b54c'::TEXT, ARRAY[2444]::BIGINT[]),
    (490::BIGINT, 'Explicando yo diría que es bueno. Pero queda a todo mundo. Literalmente. Quedó a todo mundo en estadística verano, que es de los cursos de mate más fáciles. Quedó a todo mundo en proba. Hace quices sorpresa durísimos y te da un par de minutos para terminarlo. Complica demasiado los cursos'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2025-03-08T00:00:00+00:00'::TIMESTAMPTZ, '8d23bfedfdc38e2b9bc3fc718e9de99ee274d11a62e9785db6fbc794081ed4f3'::TEXT, ARRAY[1049, 1057]::BIGINT[]),
    (490::BIGINT, 'No lleve con el mae, literalmente no sirve como profe. Los comentarios positivos son el mismo para que no le cierren los cursos porque nadie matriculo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Asistencia obligatoria']::TEXT[], '2025-02-18T00:00:00+00:00'::TIMESTAMPTZ, '7a11e762b899c312df38268870469fcbf130bd24a297f9bbe180e770f691893d'::TEXT, ARRAY[1057]::BIGINT[]),
    (490::BIGINT, 'Si va a llevar con él tiene que ser super autodidacta, estudiar con el libro y con exámenes viejos. No hay que tenerle miedo, sus clases son full teóricas pero si le pide un ejercicio lo resuelve. Lo peor de todo son sus quices que da un asco de tiempo. Si lleva mucha carga mejor no matricule.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas']::TEXT[], '2025-02-05T00:00:00+00:00'::TIMESTAMPTZ, '5e1dcc01782c3d01fe7428ab106a258122cf1e84684a72dab31fdf6c31412cc3'::TEXT, ARRAY[1057]::BIGINT[]),
    (490::BIGINT, 'Literalmente meter con el en verano fue el peor error academico, duró demasiado en dar exámenes, evalua terrible solo porque usted no pudo ver el problema como el lo veía ya mamo, el mae es súper odioso y es muy a la antigua. No meta con el mae a menos que ya sepa todo el curso, en Verano nunca.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2025-02-01T00:00:00+00:00'::TIMESTAMPTZ, '27ea3b6e9d5e8c8ab6691fe4adf50891e35040aaa10f1a7ce0a641e4ecb1f0f4'::TEXT, ARRAY[1057]::BIGINT[]),
    (490::BIGINT, 'Para este señor dar clase es leer el libro medio resolver un problema y gastar todo el tiempo de la clase explicando cosas que no sirven para el curso. Duro mucho en entregar notas y espera que usted sepa todo, el mae no ayuda y medio ve las cosas por encima. Hagase un favor y no matriculé con él.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2025-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'dda9c4734fd6d73b481730ed4e0c65d6c09aa6d1727ca1ed0492d5b99b2c0fd3'::TEXT, ARRAY[1057]::BIGINT[]),
    (490::BIGINT, 'Este mae no sirve como profesor, literalmente el mae disfruta quedando a la gente, dio los examenes hasta al puro final siempre, no daba notas para que la gente no abandonara. Evalua durisimo, si no usa el metodo que el mae queria 0 aunque este medio bueno. Espera que usted sea matematico.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2025-01-29T00:00:00+00:00'::TIMESTAMPTZ, '5dbd2fce7dfa1ff9e23491ef1fd7a686b4936cd381434f59fcba6f3011c0425f'::TEXT, ARRAY[1057]::BIGINT[]),
    (490::BIGINT, 'El profe se pierde explícando la teoría para nosotros interiorizarla y tener lógica cuando se aplica una formula. Siento que no se enfoca en la práctica, y bueno, los exámenes son solo ejercicios, entonces hay que pellizcarse y practicar por cuenta propia todo los ejercicios.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-12-18T00:00:00+00:00'::TIMESTAMPTZ, '9a666e2541832f2727ce16b5f8ad51c8bf50b9d802652b2fa112173a93f47aa0'::TEXT, ARRAY[1057]::BIGINT[]),
    (490::BIGINT, 'Terrible profesor, literalmente pierde el tiempo en clase viendo teoria matematica que no aplica para el curso, evalua durisimo para un profesor que no resuelve ejercicios, en el semestre matriculamos 8, y solo paso 1. Pide todo perfecto esperando que uno sea matematico, y tambien odia los de compu.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2024-12-17T00:00:00+00:00'::TIMESTAMPTZ, '00e3186e1812ac63f8363bd935859fa6b08ea56ab2cd9c0b5a99c6bfe3526775'::TEXT, ARRAY[1057]::BIGINT[]),
    (490::BIGINT, 'Es una persona sumamente conocedora de la matemática pero en ámbitos académicos es malo, los quizes son durísimos y sin tiempo, explica regular pero en clases pierde demasiado tiempo explicando cosas que al final no van a servir de nada, algo que rescato es que si preguntas te va a ayudar'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2024-07-24T00:00:00+00:00'::TIMESTAMPTZ, '5eea78723cc801fc5fb9187774df0a20b71f7eabea2037aa2f4995d1fe79fcf2'::TEXT, ARRAY[563]::BIGINT[]),
    (490::BIGINT, 'Los quices que hace son rudisimos, da como 4 segundos de tiempo por cada uno, ni 1 solo porcentaje de tareas, son 75% de quices y 25% de tareas, hay que ser muy autodidactico porque si va a un parcial con las clases de el lacto, lleven otro profe'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2024-06-22T00:00:00+00:00'::TIMESTAMPTZ, '05bdd413e9cec7669014aeffde64fc5fa98a8ab348c746f8a163684305462ec2'::TEXT, ARRAY[563]::BIGINT[]),
    (490::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '2e6eca73a6275a665224621278468ea612055f3aaaf66a2307f5490efc046372'::TEXT, ARRAY[605]::BIGINT[]),
    (490::BIGINT, 'Matriculen con el si sus bases en matematica son perfectas, porque el parte dando la materia asumiendo que usted sabe todo y más , ademas no deja usar calculadora, entonces es mas complicado aprender con el, realmente es casi que estudio independiente'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-06-10T00:00:00+00:00'::TIMESTAMPTZ, '99656a3dd38db313c99f81f4f26d8d8389158708dc6f012b29f37b0106b12dca'::TEXT, ARRAY[563]::BIGINT[]),
    (490::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Clases largas']::TEXT[], '2024-05-02T00:00:00+00:00'::TIMESTAMPTZ, '59bd45a17dd08fc5e045df3ca6c981cc1ee3af8f9c3ba6527a54200e047d115b'::TEXT, ARRAY[563]::BIGINT[]),
    (490::BIGINT, 'Súper mal profe, ayuda solo a sus favoritos. Nunca se equivoca y no sabe explicar bien, ve la materia por encima y ni hace ejercicios de práctica solo da la materia'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-03-07T00:00:00+00:00'::TIMESTAMPTZ, 'c12508955b6b3fb08945c83d541a955c6e37597d8ee31d06445df9671cf1407b'::TEXT, ARRAY[563]::BIGINT[]),
    (490::BIGINT, 'Casi no paso el curso, sin embargo el profesor fue sumamente comprensivo de muchos aspectos y al final logre pasar por suerte. No te perdona errores eso si, ni da puntos, pero te da las herramientas para verdaderamente entender la materia; es solo de pedírselo. Realmente es agradable.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Exámenes retadores', 'Brinda apoyo']::TEXT[], '2024-01-23T00:00:00+00:00'::TIMESTAMPTZ, '830ad057e22497531a990511b0077ac7fee9eb1bb1369a123f03867e2f2943aa'::TEXT, ARRAY[563]::BIGINT[]),
    (490::BIGINT, 'Excelente profesor, enseña muy bien, con bastante claridad, si usted le hace caso y estudia regularmente aparte de las clases, el curso no debería ser un inconveniente. Los trabajos que solicita son sumamente sencillos y los quices igual, aunque son más trabajos que quices'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-11T00:00:00+00:00'::TIMESTAMPTZ, 'e56188bd091775b3144bcf3856980c36aa28373497d4cf755cb926f0d841d6e0'::TEXT, ARRAY[563]::BIGINT[]),
    (490::BIGINT, 'El profesor es súper orgulloso, no ayuda en nada solo hacer los ejercicios que uno pregunte pero no explica bien, en clase pierde mucho tiempo y divaga entre temas, no deja actividades ni trabajos para poder tener buenas notas, es super conservador y creo tecnológico, es casi imposible pasar con el'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-01-10T00:00:00+00:00'::TIMESTAMPTZ, '78be470c70ea247a81e48dd95e4b80ca8891d2f583fbb2b40551c5411deb9aa5'::TEXT, ARRAY[563]::BIGINT[]),
    (490::BIGINT, 'Faltó a muchas clases, no enseña la materia clara, confunde a la clase hablando acerca de oros temas en vez de explicar lo necesario. Hace quices sorpresas con muy poco tiempo para realizarlos. Tuve que pedirle a un amigo que me enseñara el curso desde cero.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2023-11-20T00:00:00+00:00'::TIMESTAMPTZ, '8dea0321b88a73a2d5c36d405a91b57262d08b9723fc223cd18e510116418e6d'::TEXT, ARRAY[605]::BIGINT[]),
    (490::BIGINT, 'El profesor explica bien, sin embargo pierde mucho el tiempo hablando cosas que tal vez no se centran tanto en el curso, se atrasa y ve algunos temas por encima, cancela muchas clases y lo que deja es una guía'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Pocos exámenes']::TEXT[], '2023-10-21T00:00:00+00:00'::TIMESTAMPTZ, 'b5c28401f75ea14a5dfd05b8809334421894ff6419bc2ac46cbf6db555fba157'::TEXT, ARRAY[605]::BIGINT[]),
    (490::BIGINT, 'Pierde mucho el tiempo hablando de otras cosas que no son de la materia, no prepara bien para los exámenes no deja práctica ni da retroalimentacion, siempre quiere tener la razón y los estudiantes tienen la culpa hasta de respirar. "No deja usar calculadora"'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2023-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'a1afa59381e6cb9eeef354f213d8ce2b9f571539660c5ce711e2ad77e7ed4e25'::TEXT, ARRAY[2439]::BIGINT[]),
    (490::BIGINT, 'Se la pasa hablando de cosas que no importan y divaga mucho'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas']::TEXT[], '2023-01-19T00:00:00+00:00'::TIMESTAMPTZ, '38331aee62f04aeba3ca8dba04b9aec414582911e6349328bc8ec89e2a8a5e3f'::TEXT, ARRAY[563]::BIGINT[]),
    (490::BIGINT, 'Es muy buena nota y explica bien, el curso llega a ser rudo y la verdad el mae no lo prepara uno bien para el examen y además llega hacer muy necio con las guías semanales y puede pedirlas por sorpresa, pierde mucho tiempo hablando papaya.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Inspirador', 'Clases largas']::TEXT[], '2022-11-25T00:00:00+00:00'::TIMESTAMPTZ, '8fe2af273437b34c03027c5852363f96723fa08564cb640255bf9f0da10952be'::TEXT, ARRAY[605]::BIGINT[]),
    (490::BIGINT, 'El profe enseña bien, igual, Mate General es dificil, entonces, uno debe poner de su parte para pasar el curso. Nunca se sabe cuando revise las Guías Semanales, algunas veces dice muy claro que las va a revisar o no, el comprende que hay otros curso.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Aspectos de calificación claros']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'bd395ce201cd101f3dd706fefc367c72535d818c29658db6557ac3bf5e040b70'::TEXT, ARRAY[563]::BIGINT[]),
    (490::BIGINT, 'Es buena gente, algo estricto con las tardias al entregar. Las guias hay que hacerlas todas las semnanas nunca se sabe cuando las pide, igual hace actividades calificadas todas las semnas, pero usa varias plataformas para hacerlo distinto y llevadero.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'e4ed5f121cc5b1a1c8c0508866ac8ab1b40b196534795cefd8d8b539ef2811a9'::TEXT, ARRAY[563]::BIGINT[]),
    (490::BIGINT, 'no hubieron exámenes, el profesor explica bien. Actualizó calificaciones hasta la ultima semana.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, '93d94289b044fb7917e0a98038bf649042d2c6578c4d7b3fab33bf421cbb276b'::TEXT, ARRAY[1892]::BIGINT[]),
    (490::BIGINT, 'Es muy buena persona, es muy bueno explicando, se nota el esfuerzo que le pone a la clase.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'abf3571263d93c0ce1edb54e840ba5d4d164bc2e4d6d69acd42744581fc5892e'::TEXT, ARRAY[563]::BIGINT[]),
    (490::BIGINT, 'Es muy buena persona y buen profe, es de dejar mucho trabajo con las guías y quices, además tarda mucho en dar las notas.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Inspirador']::TEXT[], '2022-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'b1b625c98839ea538562d213a832bfa5f9f81d32f84a46445aa86a659b33fc7f'::TEXT, ARRAY[563]::BIGINT[]),
    (490::BIGINT, 'Es muy bueno explicando, pero muy insistente con los trabajos, guías semanales, y quizes, hay demasiado'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2022-06-04T00:00:00+00:00'::TIMESTAMPTZ, '3750174b09a74db9ea19db7dd37badc982c8cd5852665b98c6e6d4bae1c0398c'::TEXT, ARRAY[563]::BIGINT[]),
    (490::BIGINT, 'Explica muy bien. Pone ejemplos de la vida real y hace que uno se interese por la materia. Hace que el curso no sea ni fácil ni difícil, lo justo para un curso de ese tipo. El único problema es que dura mucho en entregar notas de exámenes y a reclamarle puntos es complicado.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2022-02-03T00:00:00+00:00'::TIMESTAMPTZ, '9d2968a15cad9ebc79d16d1bddc9ccbc15e3a9ae43b6d6cbe193eaf57dc9ab45'::TEXT, ARRAY[1057]::BIGINT[]),
    (490::BIGINT, 'En presencial todo bien, pero para virtual mejor evitelo. Cuesta que se entregue retroalimentacion por lo que uno anda a ciegas casi todo el curso, las clases las distribuye en ejercicios muy básicos y ante cualquier duda su respuesta es revisé el pdf...'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, '36c2f164aa0d9c50c6d507a80fea786340606ed820ca321548761cfabb65b168'::TEXT, ARRAY[1049]::BIGINT[]),
    (490::BIGINT, 'El profesor tiene pésimo manejo del uso de tecnologías asistidas para dar clases, la pérdida de tiempo en clases es muy excesiva incluso para ver solo un ejercicio. Lastimosamente el curso no fue del todo provechoso en mi caso y la verdad no siento que sea una buena idea llevarlo con él.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'ff6d8197d11353682f311d2bcd58ac6d73416df0f222b4f31fdcc5c8dcb42b09'::TEXT, ARRAY[1049]::BIGINT[]),
    (490::BIGINT, 'Mucha confusión con la cátedra y el profesor, no da retroalimentación y califica hasta que ya es muy tarde para corregir los errores, en presencial probablemente es un buen profesor, ya que se nota su interés en la clase, pero en virtual es mejor evitarlo.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2021-01-26T00:00:00+00:00'::TIMESTAMPTZ, '1c7823747a230289c9368ee271ad4a630e716ed3a2add5a61726de8aec8eeada'::TEXT, ARRAY[1049]::BIGINT[]),
    (490::BIGINT, 'Como muchos otros me fui con el por sus calificaciones en presencial pero su pésimo interés por la clase hace ver lo poco que le interesa que el estudiante aprenda, su explicación es muy superficial lo que hace difícil entender los temas sobre todo cuando las evaluaciones son muy difíciles.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2020-12-14T00:00:00+00:00'::TIMESTAMPTZ, 'e80b391a373bd99bb4371e1cde57a96a3189b5581eb2c363567636a9fe1026bf'::TEXT, ARRAY[1049]::BIGINT[]),
    (490::BIGINT, 'No sé en presencial, pero en virtual es el peor curso de matemáticas que he llevado. Todo está en PDF/lecturas que da la catedra y son una basura. Solo da clase una vez a la semana. Él siempre tiene la razón y lo que dice es la verdad absoluta. Lamentable y decepcionante.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-12-12T00:00:00+00:00'::TIMESTAMPTZ, '45108e863858b2f30c7113ef97a8fee2701c1374cca991388cd04ea4e8d915cb'::TEXT, ARRAY[1049]::BIGINT[]),
    (490::BIGINT, 'No puedo hablar por modalidad presencial pero en virtual es lamentable, una decepción. Me fui por las buenas calificaciones que tiene de manera presencial pero en virtual son otros 100 pesos. Busca cualquier excusa para llegar a la conclusión de que el alumno es el que está mal.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-11-16T00:00:00+00:00'::TIMESTAMPTZ, '65578bdf74a9ee0afaa2adffde409fa3c5bd1b98021992feb50eb638805f54db'::TEXT, ARRAY[1049]::BIGINT[]),
    (490::BIGINT, 'Cuando dió las clases presenciales antes de la pandemia el mae fue muy pura vida. Ojalá hubiera sido así con las clases virtuales. Pasó mes y medio (casi dos meses) sin dar una clase por zoom/jit.si dejándonos guías de clase y nada más. Tiene una pregunta que hacerle? Está en el PDF joven. Evítelo.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2020-08-28T00:00:00+00:00'::TIMESTAMPTZ, '1c56262fea69e23db4951a7a41362624fa4c63f2edb45b99f34ef7b997af0ef0'::TEXT, ARRAY[1057]::BIGINT[]),
    (490::BIGINT, 'Una lástima, en modalidad presencial Erick era súper bueno. Las clases son asíncronicas (no hay problema con eso), pero el libro es bastante escueto.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, 'd110272eaf2ad5913ec7821c6c9627d8cb0d4626c2f8ba76060c758e3e23dcb2'::TEXT, ARRAY[1057]::BIGINT[]),
    (490::BIGINT, 'Han visto el meme de "En el pdf viene joven"? Eso es el curso básicamente, una lástima porque cuando sí da clases se le entiende sin problema'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '484f0e234e209b43299c0f992228a1da31b102be0fcecfdd25c1a7d44752f312'::TEXT, ARRAY[1057]::BIGINT[]),
    (490::BIGINT, 'Lo que fueron clases presenciales un 100, pero el profe no es bueno para virtual. Las clases son muy largas, no retiene la atención de los estudiantes. da muchas vueltas y dura mucho para explicar 1 ejercicio. Llévelo si está repitiendo por poco o si es bien autodidacta y 0 procrastinador'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases largas']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '38db84f5ec6b9be38c52e5f79d54f4b1238da05cb1415993c8962b403da6c565'::TEXT, ARRAY[605]::BIGINT[]),
    (490::BIGINT, 'Probabilidades es, discutiblemente, de los cursos más complicados de mate. Sin embargo, este profe hizo el curso muy sencillo, explica excelente y se interesa demasiado por que todos los estudiantes entiendan. Si puede meter con él, HÁGALO. Mejor profe de mate.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-03T00:00:00+00:00'::TIMESTAMPTZ, '778afb4b3076b38b94bd4fb2615fb8a5cd79011d7e5a06dbadcd35256dcab013'::TEXT, ARRAY[1049]::BIGINT[]),
    (490::BIGINT, 'Explica muy claro aunque algunas veces se desvia mucho de mate para explicar historia de la mate que si le interesa puede servir para la vida si no le interesa sera aburrido.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-02T00:00:00+00:00'::TIMESTAMPTZ, 'f53c95fe30ee629a1cd38a95823c052af268961f52804f84053d9f67afcd39ad'::TEXT, ARRAY[605]::BIGINT[]),
    (490::BIGINT, 'Excelente profesor, explica claro y da muchos ejemplos. Super recomendado, eso sí, revisen que el curso no sea semivirtual porque en esa modalidad no se aprovecha la clase como se debería.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'fd2ca0c277394bb8a930665421c78d81a4af92ae4cba9365e64e98accc41122e'::TEXT, ARRAY[563]::BIGINT[]),
    (490::BIGINT, 'No pude pedir un mejor profe de mate. Muy atento y ayuda siempre, ninguna duda es muy tonta porque las resuelve todas, tiende a perder un poco el tiempo pero nunca va corriendo. Es muy amable con los estudiantes y todos en la clase lo queríamos.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '954a6649def2a45dd5a5ef8e54c14a2c36d34542776f402c9f12f909d24b1838'::TEXT, ARRAY[563]::BIGINT[]),
    (490::BIGINT, 'El profe es muy bueno, solo hay que saber aprovecharlo, le gusta que le pregunten el porque de las cosas y sabe cuando alguien le interesa la clase. A veces se distrae un poco y pierde un poco el tiempo, pero nada muy grave, en fin, excelente profe'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2019-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'ef82a702ac337cf6a1225462998cac026e537efbc0e51bbe62394f8b82434858'::TEXT, ARRAY[563]::BIGINT[]),
    (490::BIGINT, 'Explica bastante bien, hace suficientes ejemplos, sin embargo a veces explica mas de la cuenta y se atrasa con la materia. Genera un ambiente agradable en la clase, repone clases si es necesario, en general bastante bueno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'ca8788e7162736f086f32304ced0a0f659d9a45234720caec1144a423d70af58'::TEXT, ARRAY[563]::BIGINT[]),
    (490::BIGINT, 'falto dos semanas durante el semestre por reuniones, explica super complejo'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2019-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'af1a1c6af3c023462564406a6309a51356e5c0d06adb2ee2dc6a758e3df50253'::TEXT, ARRAY[1049]::BIGINT[]),
    (490::BIGINT, 'Es un profe súper chiva. Siempre se termina yendo por las ramas cuando está explicando, y le cuenta la vida de él, por lo tanto es algo lento para dar la materia. Explica demasiado bien, súper recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-15T00:00:00+00:00'::TIMESTAMPTZ, '4f7792e9a732e5931913064f153ecc8de8a7a86fa84b7032ed6fa1d468199bf2'::TEXT, ARRAY[563]::BIGINT[]),
    (490::BIGINT, 'Deja la materia súper clara y es fácil de entender. De veras le importa que sus estudiantes aprendan. Lo único es que pierde mucho tiempo en clase. Hizo que la mate me gustara'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Clases excelentes']::TEXT[], '2019-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'e317c36bc7816b6e1b82dab8b6dc8c78bf7ff2e79f1a28bee0affe58c29e7b5b'::TEXT, ARRAY[563]::BIGINT[]),
    (490::BIGINT, 'Excelente profesor, además es pura vida; eso sí, deja tareas muy largas, aunque se hacen en grupos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-09T00:00:00+00:00'::TIMESTAMPTZ, '2793d538c2180cac679fe55c5adb4ed474636a5c034e8f9679eb6faac627cdab'::TEXT, ARRAY[563]::BIGINT[]),
    (490::BIGINT, 'Vea yogur, ese grupito de atrás, todos pasamos, vaya llorele a su mamá.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases largas']::TEXT[], '2018-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'b33b121d4f7137db85f6c7320549eac3f737b5b4a742a1d470eecff763b289d0'::TEXT, ARRAY[1049]::BIGINT[]),
    (490::BIGINT, 'Al que dijo que las clases eran aburridas de seguro era del grupito que pasaban hablando y no dejaban poner a los demás atención...Mamap***. El profe es un crack. Enseña la materia y lo que hay debajo por lo que uno entiende todo. Hace buenos ejemplos y se preocupa por los estudiantes. Dele de una!!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-29T00:00:00+00:00'::TIMESTAMPTZ, '698d0c83939bb8a7103f07a621a973aab3686b10403c59bf75385b3590593370'::TEXT, ARRAY[1049]::BIGINT[]),
    (490::BIGINT, 'Le encanta la materia, por lo que explica los temas con matemáticas muy profundas, por lo que hace pocos ejercicios parecidos a los que vienen en el examen y hace cosas muy complejas. Si se quiere solo pasar el curso, no es el mejor, pero si quiere entender todo lo que hay detrás, este es el mejor.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, '0996122151574f25bc35a032568ab2b6e2b0a3603ab917ac8a8532e0aab6813f'::TEXT, ARRAY[1049]::BIGINT[]),
    (490::BIGINT, 'Es buen profesor. Sabe explicar bien. Se enoja si uno lee las páginas que deja de tarea. Califica los exámenes de forma normal.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-11-21T00:00:00+00:00'::TIMESTAMPTZ, '38a651a3ec12cefa12c1a74de24ff669b5c2c06c92523eb4bf7691cbc9ece712'::TEXT, ARRAY[1049]::BIGINT[]),
    (490::BIGINT, 'El profe cree que es el único curso que se lleva en el semestre, deja lecturas y se molesta si uno no las lee. Califica duro y las clases son demasiado aburridas.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'dbed05fcab4067fa61b305091415ef44a240781aa924e22b7f04dac90e6d2a8f'::TEXT, ARRAY[1049]::BIGINT[]),
    (490::BIGINT, 'Es simple y sencillamente el mejor profe de la escuela, súper paciente y amable. Sabe demasiadas cosas y uno sale hasta sabiendo de más para otros cursos. Matricule con el a ojos cerrados porque va a aprender montones en un ambiente super bonito.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-09-09T00:00:00+00:00'::TIMESTAMPTZ, 'b3298075e968e7dec6b644fc3af3f082df1b7fa169a9cc9b52a03dc5f61ea536'::TEXT, ARRAY[563]::BIGINT[]),
    (490::BIGINT, 'Demasiado bueno para dar la clase y la metologia con la que lo hace es muy sutil y ordenada, sabe demasiado y eso hace los ratos en clase muy entretenidos gracias a su conocimiento. Califica duro.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '12f7b7c7be5ce683cebb235fb214b677e8fb196b16e39862de7f6fbcef172244'::TEXT, ARRAY[563]::BIGINT[]),
    (490::BIGINT, 'Explica excelente. Todo se le entiende y repite las veces que sean necesarias. Le interesa que uno de verdad aprenda de donde salen las cosas y no simplemente a resolver ejercicios. Ayuda bastante y se ve que disfruta lo que hace. Califica rudo pero se preocupa mucho por que los estudiantes aprendan'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '4862f8ed15810c155587c5793e8e3551af9d853ea58cc809ba42589242bc1c85'::TEXT, ARRAY[1041]::BIGINT[]),
    (490::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'f8fc636478b78ab18d8609b2b63b670a168ad1fcb752ea151878fbfa81b081b1'::TEXT, ARRAY[2439]::BIGINT[]),
    (490::BIGINT, 'Un excelente profesor, explica super claro, se preocupa porque uno aprenda para el futuro,ademas de que es buena gente.Solamente califica bastante duro,no regala nada pero asi es el TEC.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '2bb1ac8deb1ea0a2f7e168bff856d7a46bd9be549aff1cf6416ded3f4f01be5d'::TEXT, ARRAY[1041]::BIGINT[]),
    (490::BIGINT, 'Es excelente, sabe tanto que uno aprende hasta de otros temas en sus clases, son cero tediosas y tiene mucha paciencia para explicar.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-06-14T00:00:00+00:00'::TIMESTAMPTZ, '1fabe09ab61cf0ded1be12267251390546f56b3766f17abe517c9bca35b3d3e2'::TEXT, ARRAY[2439]::BIGINT[]),
    (490::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2018-05-29T00:00:00+00:00'::TIMESTAMPTZ, '3700719c0677dda0ceb03636c1b4e5ca91a91dc18c3df41af5c9c57a8f2638c6'::TEXT, ARRAY[2439]::BIGINT[]),
    (490::BIGINT, 'Excelente profesor, explica la materia súper bien pero califica súper fuerte, es el mejor para dar este curso. No ayuda en nada al final del curso.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2018-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'fe259bd930daf361bb3bd9ca5ae3a6fcda954603b305c0995bcc2735d3cb0804'::TEXT, ARRAY[1049]::BIGINT[]),
    (490::BIGINT, 'Facil uno de los mejores profes de la escuela de mate. Recomendado para cualquier curso. Se enfoca en que el estudiante aprenda como se hacen las cosas y de donde salen,'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-30T00:00:00+00:00'::TIMESTAMPTZ, '447c48c5957bc625a5a7c3434d6b6b0a26d97a3c61cb4104e5941e29f917fd2e'::TEXT, ARRAY[1049]::BIGINT[]),
    (490::BIGINT, 'Explica muy bien aunque aveces complica las cosas más de la cuenta, sáquenle provecho a las horas consulta porque ayuda mucho, este semestre hizo quices fáciles. No da ningún punto por más que se le pida.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2017-12-16T00:00:00+00:00'::TIMESTAMPTZ, 'cc4c57d428cf2bb1fba7b7e6615a6a55dbe8ae9eafad6f059df45b4be6cccfdc'::TEXT, ARRAY[1049]::BIGINT[]),
    (490::BIGINT, 'Este semestre estaba explicando más confuso segun el sistema nuevo semivirtual es un dolor de cabeza hasta para el profe, no funciona, siento que los problemas venían de la cátedra y el tecDigital, pero el hizo lo que pudo para ayudar, hay que mentalizarse de que se está solo en el curso.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2017-12-05T00:00:00+00:00'::TIMESTAMPTZ, '2ba28e88fe5cc5ff3f23b75af25fed0cf016a98b07e29d1e23bf247a54872e90'::TEXT, ARRAY[1049]::BIGINT[]),
