    (490::BIGINT, 'Muy bueno, súper recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2017-10-09T00:00:00+00:00'::TIMESTAMPTZ, '514536319fd02fa2169068a5170d828a7394309b73ec282856fe9d76fa02d7e3'::TEXT, ARRAY[563]::BIGINT[]),
