    (490::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'e5eb24ab62745997bd726e34c6f95442951f7390765dda90413c120cd39a3356'::TEXT, ARRAY[1049]::BIGINT[]),
    (490::BIGINT, 'Es un gran profesor, explica muy bien y tarda lo que tenga que tardar, es responsable y tiene vocación. Lo único malo fue que tarda mucho para dar las calificaciones'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-19T00:00:00+00:00'::TIMESTAMPTZ, '93dea1a30ecfbf9cd804ea3c21097cd397b5441eb0327c5649a50ff5351898a3'::TEXT, ARRAY[1041]::BIGINT[]),
    (490::BIGINT, 'El profe es muy tuanis y ayuda mucho para que el estudiante entienda la materia, es rudo calificando los exámenes. En general es excelente profesor.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'e1c78286134c5da2258b122446a7ff68f60610b5e804ca2c14228b1193065ac9'::TEXT, ARRAY[1041]::BIGINT[]),
    (490::BIGINT, 'Excelente. Es muy amigable con el estudiante. Espero que uno entienda y explica las veces que sean. Un profe con vocación, algo poco usual :O'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'f641a0bf282c921b7b42c64cbf27725da078f659b7f06fc8909951a0b654c1a0'::TEXT, ARRAY[1049]::BIGINT[]),
    (490::BIGINT, 'El profe es muy tuanis, él se toma su tiempo para explicar las cosas y si debe explicarlo 10 veces lo hace con mucho gusto. No le importa salir a la hora que sea cuando se trata de una clase de repaso para el examen o simplemente horas de consulta; él quiere que uno aprenda. Califica lo justo!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-02-07T00:00:00+00:00'::TIMESTAMPTZ, '12714002f10d0a413c5f62afd77f28caac0535f300613ec7d9bc767baf5036d5'::TEXT, ARRAY[605]::BIGINT[]),
