    (490::BIGINT, 'Excelente si pueden matriculen con el'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-11-15T00:00:00+00:00'::TIMESTAMPTZ, '49ae1b166cb0922e1032aceebea3eaed5914fd0927c297897cdf0ba0a462f19f'::TEXT, ARRAY[563]::BIGINT[]),
    (490::BIGINT, 'Súper recomendado, es de esos profesores que si les interesa que el estudiante aprenda. Da más hora consulta del que le pagan.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Brinda apoyo']::TEXT[], '2016-11-03T00:00:00+00:00'::TIMESTAMPTZ, '392835a7799ec43b4edf06b5549ed16791f960413b016dd19b2ee3fa63ab6636'::TEXT, ARRAY[563]::BIGINT[]),
