    (490::BIGINT, 'Excelente profesor, recomendado.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-07-06T00:00:00+00:00'::TIMESTAMPTZ, '1ea168a5bdd44c5aec04b28f90fb60b113823b8d0c169965467be9f3f16e623e'::TEXT, ARRAY[1041]::BIGINT[]),
    (490::BIGINT, 'Excelente profesor, es de esos profesores que verdaderamente se preocupa por que cada uno de sus estudiantes comprendan la materia, incluso si tiene que dar más del tiempo por el que le pagan!.. No deja muchas tareas, califica suave, y lo mejor: Es bastante bueno explicando. Lo recomiendo al 100%'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-03-25T00:00:00+00:00'::TIMESTAMPTZ, 'd9181599dc89b8c9de0f9d63c08f3b8d180bf3c86bf02bc5bf7e8a3ac4ddea66'::TEXT, ARRAY[563, 2920]::BIGINT[]),
